-- Eprocurement schema for CodeIgniter 4.7.4 / MySQL 8+
-- Recommended: use `php spark migrate`; this file is provided for manual deployment.
CREATE TABLE IF NOT EXISTS companies (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(160) NOT NULL UNIQUE, address TEXT NULL, phone VARCHAR(40) NULL, email VARCHAR(160) NULL, pic_name VARCHAR(120) NULL, pic_phone VARCHAR(40) NULL, notes TEXT NULL, created_at DATETIME NULL, updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS products (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, sku VARCHAR(80) NULL, name VARCHAR(180) NOT NULL, brand VARCHAR(120) NULL, description TEXT NULL, datasheet TEXT NULL, image_url VARCHAR(500) NULL, cost_price DECIMAL(18,2) NOT NULL DEFAULT 0, selling_price DECIMAL(18,2) NOT NULL DEFAULT 0, store_name VARCHAR(160) NULL, store_url VARCHAR(500) NULL, store_phone VARCHAR(40) NULL, store_pic VARCHAR(120) NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX idx_products_sku (sku)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotations (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id INT UNSIGNED NOT NULL, quotation_no VARCHAR(60) NOT NULL, customer_name VARCHAR(180) NULL, customer_address TEXT NULL, customer_phone VARCHAR(40) NULL, title VARCHAR(220) NOT NULL, valid_until DATE NULL, notes TEXT NULL, status VARCHAR(30) NOT NULL DEFAULT 'draft', subtotal DECIMAL(18,2) NOT NULL DEFAULT 0, tax_percent DECIMAL(5,2) NOT NULL DEFAULT 0, tax_amount DECIMAL(18,2) NOT NULL DEFAULT 0, grand_total DECIMAL(18,2) NOT NULL DEFAULT 0, created_at DATETIME NULL, updated_at DATETIME NULL, INDEX idx_quotations_company (company_id), CONSTRAINT fk_quotations_company FOREIGN KEY (company_id) REFERENCES companies(id) ON DELETE CASCADE ON UPDATE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS quotation_items (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quotation_id INT UNSIGNED NOT NULL, product_id INT UNSIGNED NULL, product_name VARCHAR(180) NOT NULL, description TEXT NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 1, unit VARCHAR(30) NOT NULL DEFAULT 'pcs', unit_price DECIMAL(18,2) NOT NULL DEFAULT 0, discount_percent DECIMAL(5,2) NOT NULL DEFAULT 0, line_total DECIMAL(18,2) NOT NULL DEFAULT 0, INDEX idx_items_quotation (quotation_id), CONSTRAINT fk_items_quotation FOREIGN KEY (quotation_id) REFERENCES quotations(id) ON DELETE CASCADE ON UPDATE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
